#!/usr/bin/env bash
# Basalt's full check: unit tests, worldgen parity vs vanilla, bot scenarios vs Basalt,
# differential runs vs the vanilla test server, and an optional real-client smoke test.
#
# usage: tools/check-all.sh [--quick] [--no-vanilla] [--real-client] [--ci]
#   --quick        one parity seed, smaller compare radius
#   --no-vanilla   don't use the running vanilla server (no differential phase)
#   --real-client  launch the official client against Basalt (macOS launcher install)
#   --ci           = --quick --no-vanilla, no real client; parity world generated by the server jar
# env: VANILLA_ADDR (127.0.0.1:25566), VANILLA_DIR (vanilla/srv), PARITY_SEEDS ("12345 42 1"),
#      CHECK_JOBS (4), JAVA (java)
# Output: a pass/fail table grouped by milestone; target/check/results.json; exit 1 on any failure.
set -uo pipefail
cd "$(dirname "$0")/.."
QUICK=0; VANILLA=1; REAL=0; CI=0
for a in "$@"; do
  case "$a" in
    --quick) QUICK=1 ;; --no-vanilla) VANILLA=0 ;; --real-client) REAL=1 ;;
    --ci) CI=1; QUICK=1; VANILLA=0; REAL=0 ;;
    *) echo "unknown option $a"; exit 2 ;;
  esac
done
OUT=target/check
mkdir -p "$OUT"
rm -f "$OUT"/phase-*.json "$OUT"/scenarios.json
JAVA=${JAVA:-java}
VANILLA_ADDR=${VANILLA_ADDR:-127.0.0.1:25566}
VANILLA_DIR=${VANILLA_DIR:-vanilla/srv}
SEEDS=${PARITY_SEEDS:-"12345 42 1"}
[ $QUICK = 1 ] && SEEDS=${PARITY_SEEDS:-12345}
RADIUS=3; [ $QUICK = 1 ] && RADIUS=2
JOBS=${CHECK_JOBS:-4}

# row GROUP NAME PASS(0/1) SECS DETAILS -> appended to $OUT/phase-rows.jsonl
row() { python3 -c 'import json,sys; print(json.dumps({"group":sys.argv[1],"id":sys.argv[2],"server":sys.argv[3],"pass":sys.argv[4]=="1","secs":float(sys.argv[5]),"failures":[] if sys.argv[4]=="1" else [sys.argv[6]],"notes":[sys.argv[6]]}))' "$@" >> "$OUT/phase-rows.jsonl"; }
rm -f "$OUT/phase-rows.jsonl"
now() { python3 -c 'import time; print(time.time())'; }
since() { python3 -c "import time; print(round(time.time()-$1,1))"; }

echo "== build"
T=$(now)
cargo build --release -p basalt-server -p basalt-check -q 2>&1 | tail -20
[ -x target/release/basalt-server ] && [ -x target/release/basalt-check ] || { echo "build failed"; exit 1; }
cargo build --release -p basalt-worldgen --example compare -q || { echo "compare example build failed"; exit 1; }
row Build "cargo build --release" basalt 1 "$(since $T)" "server, check, worldgen compare"

# ---------------------------------------------------------------- 1. unit tests
echo "== cargo test --workspace"
T=$(now)
if cargo test --workspace -q > "$OUT/cargo-test.log" 2>&1; then
  row Tests "cargo test --workspace" basalt 1 "$(since $T)" "$(grep -E '^test result' "$OUT/cargo-test.log" | awk '{s+=$4} END {print s" tests passed"}')"
else
  row Tests "cargo test --workspace" basalt 0 "$(since $T)" "$(grep -E 'FAILED|panicked|error' "$OUT/cargo-test.log" | head -3 | tr '\n' ' ')"
fi

# ---------------------------------------------------------------- 2. worldgen parity
# Vanilla reference worlds: generated headless by the official server jar, cached per seed+version
gen_vanilla_world() { # seed -> vanilla/parity/<seed>/world
  local seed=$1 dir=vanilla/parity/$1
  [ -f "$dir/done-26.2" ] && return 0
  [ -f vanilla/server.jar ] || { echo "vanilla/server.jar missing (run tools/extract-data.sh)"; return 1; }
  rm -rf "$dir"; mkdir -p "$dir"
  local port; port=$(python3 -c 'import socket; s=socket.socket(); s.bind(("",0)); print(s.getsockname()[1])')
  echo "eula=true" > "$dir/eula.txt"
  cat > "$dir/server.properties" <<EOF
level-seed=$seed
server-port=$port
online-mode=false
level-type=minecraft\:normal
generate-structures=true
spawn-protection=0
view-distance=2
simulation-distance=2
max-tick-time=-1
pause-when-empty-seconds=-1
network-compression-threshold=-1
sync-chunk-writes=false
EOF
  rm -f "$dir/console.fifo"; mkfifo "$dir/console.fifo"
  ( cd "$dir" && exec "$JAVA" -Xmx2G -jar ../../server.jar nogui < console.fifo > server.log 2>&1 ) &
  local pid=$!
  exec 7> "$dir/console.fifo"
  local t=0
  until grep -q "Done (" "$dir/server.log" 2>/dev/null; do sleep 1; t=$((t+1)); [ $t -gt 300 ] && { echo "vanilla server for seed $seed didn't start"; kill $pid; exec 7>&-; return 1; }; done
  # force-load chunks -5..4 (one ring more than the compared -3..3), wait until saved full
  echo "forceload add -80 -80 79 79" >&7
  local region=$dir/world/dimensions/minecraft/overworld/region ok=0
  for _ in $(seq 1 40); do
    sleep 5
    echo "save-all flush" >&7; sleep 2
    if [ -d "$region" ] && ./target/release/examples/compare "$region" 0 0 3 "$seed" 2>/dev/null | grep -q "chunks=49 "; then ok=1; break; fi
  done
  echo "stop" >&7; exec 7>&-
  wait $pid 2>/dev/null
  [ $ok = 1 ] && touch "$dir/done-26.2"
  [ $ok = 1 ]
}

echo "== worldgen parity (seeds: $SEEDS)"
for seed in $SEEDS; do
  T=$(now)
  if ! gen_vanilla_world "$seed" > "$OUT/parity-gen-$seed.log" 2>&1; then
    row M3 "parity seed $seed" basalt 0 "$(since $T)" "vanilla world generation failed: $(tail -2 "$OUT/parity-gen-$seed.log" | tr '\n' ' ')"; continue
  fi
  region=vanilla/parity/$seed/world/dimensions/minecraft/overworld/region
  res=$(./target/release/examples/compare "$region" 0 0 $RADIUS "$seed" 2> "$OUT/parity-$seed.err" | tee "$OUT/parity-$seed.log" | grep '^RESULT')
  # thresholds: biomes >= 99.9, shape >= 99.0, exact >= 98.5, features >= 98.5
  verdict=$(python3 - "$res" <<'EOF'
import sys
kv = dict(p.split("=", 1) for p in sys.argv[1].split()[1:])
th = {"biomes": 99.9, "shape": 99.0, "exact": 98.5, "features": 98.5}
bad = [f"{k} {kv.get(k)} < {v}" for k, v in th.items() if float(kv.get(k, 0)) < v]
print(("1 " if not bad else "0 ") + " ".join(f"{k}={kv.get(k)}" for k in th) + (" | " + "; ".join(bad) if bad else ""))
EOF
)
  row M3 "parity seed $seed r$RADIUS" basalt "${verdict%% *}" "$(since $T)" "${verdict#* }"
done
[ -f vanilla/parity/12345/done-26.2 ] && export VANILLA_WORLD=vanilla/parity/12345/world

# ---------------------------------------------------------------- 3+4. scenarios (and differential)
T=$(now)
if [ $VANILLA = 1 ]; then
  echo "== scenarios vs Basalt + differential vs vanilla $VANILLA_ADDR"
  ./target/release/basalt-check --diff --vanilla "$VANILLA_ADDR" --vanilla-dir "$VANILLA_DIR" --jobs "$JOBS" --json "$OUT/scenarios.json" > "$OUT/scenarios.log" 2>&1
else
  echo "== scenarios vs Basalt"
  ./target/release/basalt-check --jobs "$JOBS" --json "$OUT/scenarios.json" > "$OUT/scenarios.log" 2>&1
fi
SCEN_SECS=$(since $T)

# ---------------------------------------------------------------- 5. real client smoke
if [ $REAL = 1 ]; then
  echo "== real client smoke"
  T=$(now)
  PORT=$(python3 -c 'import socket; s=socket.socket(); s.bind(("",0)); print(s.getsockname()[1])')
  ./target/release/basalt-server --memory --flat --port "$PORT" --no-spawning > "$OUT/realclient-server.log" 2>&1 &
  SRV=$!
  for _ in $(seq 1 100); do grep -q "listening" "$OUT/realclient-server.log" && break; sleep 0.2; done
  LOG=vanilla/mcclient/logs/latest.log
  rm -f "$LOG"
  python3 tools/run-vanilla-client.py "127.0.0.1:$PORT" CheckReal > "$OUT/realclient.out" 2>&1 &
  CL=$!
  joined=0
  for _ in $(seq 1 120); do grep -q "\[CHAT\] CheckReal joined the game" "$LOG" 2>/dev/null && { joined=1; break; }; sleep 1; done
  sleep 8
  swift tools/mc-window-shot.swift "$OUT/realclient.png" > /dev/null 2>&1 || true
  errs=$(grep -iE "Failed to decode|Network Protocol Error|Disconnected|Error decoding|Exception in thread|packet.*error|lost connection" "$LOG" 2>/dev/null | grep -v "profile key pair" | head -3 | tr '\n' ' ')
  pkill -f net.minecraft.client.main.Main 2>/dev/null; kill $CL 2>/dev/null
  kill -INT $SRV 2>/dev/null; wait $SRV 2>/dev/null
  srv_errs=$(grep -E "bad packet|panicked" "$OUT/realclient-server.log" | head -2 | tr '\n' ' ')
  if [ $joined = 1 ] && [ -z "$errs$srv_errs" ]; then row "Real client" "vanilla 26.2 client joins Basalt" basalt 1 "$(since $T)" "joined; screenshot $OUT/realclient.png"
  else row "Real client" "vanilla 26.2 client joins Basalt" basalt 0 "$(since $T)" "joined=$joined $errs $srv_errs"; fi
fi

# ---------------------------------------------------------------- report
python3 - "$OUT" "$SCEN_SECS" <<'EOF'
import json, sys, os
out, scen_secs = sys.argv[1], float(sys.argv[2])
rows = [json.loads(l) for l in open(os.path.join(out, "phase-rows.jsonl"))] if os.path.exists(os.path.join(out, "phase-rows.jsonl")) else []
sp = os.path.join(out, "scenarios.json")
scen = json.load(open(sp)) if os.path.exists(sp) else [{"group": "M1", "id": "scenario runner", "server": "basalt", "pass": False, "secs": scen_secs, "failures": ["runner produced no results (see target/check/scenarios.log)"], "notes": []}]
rows += scen
order = ["Build", "Tests", "M1", "M2", "M3", "M4", "M5", "Env", "Items", "Diff", "Real client"]
rows.sort(key=lambda r: (order.index(r["group"]) if r["group"] in order else 99, r["id"], r["server"]))
fails = [r for r in rows if not r["pass"]]
w = max(len(r["id"]) for r in rows) if rows else 10
print(f"\n{'group':11} {'check':{w}} {'server':8} {'result':6} {'time':>7}  details")
group = None
for r in rows:
    if r["group"] != group and group is not None: print()
    group = r["group"]
    det = "; ".join(r["failures"]) if not r["pass"] else (r["notes"][0] if r.get("notes") else "")
    print(f"{r['group']:11} {r['id']:{w}} {r['server']:8} {'pass' if r['pass'] else 'FAIL':6} {r['secs']:>6.1f}s  {det[:150]}")
groups = {}
for r in rows: g = groups.setdefault(r["group"], [0, 0, 0.0]); g[0] += r["pass"]; g[1] += 1; g[2] += r["secs"]
print("\nsummary: " + ", ".join(f"{g} {p}/{n}" for g, (p, n, _) in sorted(groups.items(), key=lambda kv: order.index(kv[0]) if kv[0] in order else 99)))
print(f"scenario phase wall time {scen_secs:.0f}s; {len(fails)} failure(s)")
json.dump({"pass": not fails, "failures": len(fails), "scenario_wall_secs": scen_secs, "results": rows}, open(os.path.join(out, "results.json"), "w"), indent=2)
sys.exit(1 if fails else 0)
EOF
